<body>

<h1>Billiards</h1>

<div id="wrap"><canvas id="cv"></canvas></div>

<div id="bar">
  <button id="rack">Reset / Rack</button>
  <button id="pauseBtn">Pause</button>
  <div id="status">Ready — take your shot</div>
</div>

<div id="help">
  <b>How to shoot:</b> press the mouse on the <b>white cue ball</b>, drag
  <b>backwards</b> (away from where you want it to go) and <b>release</b> to strike.
  The further you drag, the harder the shot. A dashed aim line and power bar show
  direction and strength while you drag. Press <b>Reset / Rack</b> to re-rack the balls,
  or <b>R</b> on the keyboard. Sink the colours in the six pockets.
</div>

<script>
(function(){
"use strict";

/* ------------------------------------------------------------------ *
 *  Geometry / constants
 * ------------------------------------------------------------------ */
const W = 800;              // playfield width  (px)
const H = 400;              // playfield height (px)
const R = 11;               // ball radius      (px)
const MARGIN = 34;          // wooden rail thickness around the playfield

const POCKET_R   = 19;      // capture radius of a pocket (ball centre inside => potted)
const POCKET_DRAW= 21;
const FRICTION   = 0.72;    // exponential rolling-decay rate (1/s)
const STOP_SPEED = 5;       // px/s below which a ball is considered at rest
const RESTITUTION= 0.99;    // near-elastic ball/ball
const CUSHION_E  = 0.94;    // rails absorb a little
const MAX_SHOT   = 1400;    // px/s
const SUB_DT     = 1/480;   // fixed physics sub-step (determinism)

const POCKETS = [
  {x:0,   y:0}, {x:W/2, y:0}, {x:W,   y:0},
  {x:0,   y:H}, {x:W/2, y:H}, {x:W,   y:H}
];

const COLORS = {
  0:"#f7f5ef",
  1:"#f4c518", 2:"#1f4fbf", 3:"#d8322b", 4:"#6b2fb5", 5:"#e8801f",
  6:"#1c8a4a", 7:"#7d2b1f", 8:"#141414",
  9:"#f4c518",10:"#1f4fbf",11:"#d8322b",12:"#6b2fb5",13:"#e8801f",
 14:"#1c8a4a",15:"#7d2b1f"
};

/* ------------------------------------------------------------------ *
 *  Canvas
 * ------------------------------------------------------------------ */
const cv  = document.getElementById("cv");
const ctx = cv.getContext("2d");
const DPR = Math.max(1, Math.min(2, window.devicePixelRatio || 1));
cv.style.width  = (W + MARGIN*2) + "px";
cv.style.height = (H + MARGIN*2) + "px";
cv.width  = Math.round((W + MARGIN*2) * DPR);
cv.height = Math.round((H + MARGIN*2) * DPR);
ctx.scale(DPR, DPR);

/* ------------------------------------------------------------------ *
 *  State
 * ------------------------------------------------------------------ */
let balls = [];             // {x,y,vx,vy,potted,cue,n}
let running = true;
let rafId = null;
let lastT = null;

function num(v, d){ return (typeof v === "number" && isFinite(v)) ? v : d; }

function makeBall(spec, idx){
  return {
    x: num(spec && spec.x, 0),
    y: num(spec && spec.y, 0),
    vx: num(spec && spec.vx, 0),
    vy: num(spec && spec.vy, 0),
    potted: !!(spec && spec.potted),
    cue: !!(spec && spec.cue),
    n: (spec && typeof spec.n === "number") ? spec.n : idx
  };
}

function reset(list){
  if (Array.isArray(list)){
    balls = list.map(makeBall);
  } else {
    balls = rackLayout().map(makeBall);
  }
  drag.active = false;
  draw();
  return state();
}

/* Standard triangle rack + cue ball on the head spot. */
function rackLayout(){
  const out = [];
  out.push({x: W*0.25, y: H/2, vx:0, vy:0, cue:true, n:0});

  const order = [1,9,2,10,8,3,11,4,12,5,13,6,14,7,15]; // 8-ball in the centre
  const apexX = W*0.68, apexY = H/2;
  const gap = 2*R + 0.6;
  let k = 0;
  for (let row=0; row<5; row++){
    for (let i=0; i<=row; i++){
      const x = apexX + row * gap * Math.sin(Math.PI/3);
      const y = apexY + (i - row/2) * gap;
      out.push({x:x, y:y, vx:0, vy:0, cue:false, n: order[k++]});
    }
  }
  return out;
}

function state(){
  return balls.map(b => ({
    x:b.x, y:b.y, vx:b.vx, vy:b.vy, potted:b.potted, cue:b.cue
  }));
}

/* ------------------------------------------------------------------ *
 *  Physics
 * ------------------------------------------------------------------ */
function substep(h){
  const decay = Math.exp(-FRICTION * h);

  // 1. friction + integration
  for (let i=0;i<balls.length;i++){
    const b = balls[i];
    if (b.potted) continue;
    b.vx *= decay;
    b.vy *= decay;
    const sp2 = b.vx*b.vx + b.vy*b.vy;
    if (sp2 < STOP_SPEED*STOP_SPEED){ b.vx = 0; b.vy = 0; continue; }
    b.x += b.vx * h;
    b.y += b.vy * h;
  }

  // 2. pockets (checked before the cushions so a ball can drop in)
  for (let i=0;i<balls.length;i++){
    const b = balls[i];
    if (b.potted) continue;
    for (let p=0;p<POCKETS.length;p++){
      const dx = b.x - POCKETS[p].x, dy = b.y - POCKETS[p].y;
      if (dx*dx + dy*dy <= POCKET_R*POCKET_R){
        b.potted = true; b.vx = 0; b.vy = 0;
        break;
      }
    }
  }

  // 3. cushions — always keep the centre inside [R, W-R] x [R, H-R]
  for (let i=0;i<balls.length;i++){
    const b = balls[i];
    if (b.potted) continue;
    if (b.x < R)     { b.x = R;     if (b.vx < 0) b.vx = -b.vx * CUSHION_E; }
    else if (b.x > W-R){ b.x = W-R; if (b.vx > 0) b.vx = -b.vx * CUSHION_E; }
    if (b.y < R)     { b.y = R;     if (b.vy < 0) b.vy = -b.vy * CUSHION_E; }
    else if (b.y > H-R){ b.y = H-R; if (b.vy > 0) b.vy = -b.vy * CUSHION_E; }
  }

  // 4. ball / ball collisions (equal mass, along the line of centres)
  const D = 2*R;
  for (let i=0;i<balls.length;i++){
    const a = balls[i];
    if (a.potted) continue;
    for (let j=i+1;j<balls.length;j++){
      const b = balls[j];
      if (b.potted) continue;
      let dx = b.x - a.x, dy = b.y - a.y;
      let d2 = dx*dx + dy*dy;
      if (d2 >= D*D) continue;

      let d = Math.sqrt(d2);
      let nx, ny;
      if (d > 1e-9){ nx = dx/d; ny = dy/d; }
      else { nx = 1; ny = 0; d = 0; }

      // positional de-overlap (split evenly, equal mass)
      const overlap = (D - d) * 0.5 + 1e-6;
      a.x -= nx*overlap; a.y -= ny*overlap;
      b.x += nx*overlap; b.y += ny*overlap;

      // relative normal velocity
      const rvn = (b.vx - a.vx)*nx + (b.vy - a.vy)*ny;
      if (rvn >= 0) continue;                  // already separating
      const jimp = -(1 + RESTITUTION) * rvn * 0.5;   // masses = 1
      a.vx -= jimp*nx; a.vy -= jimp*ny;
      b.vx += jimp*nx; b.vy += jimp*ny;
    }
  }
}

function step(dt){
  dt = num(dt, 0);
  if (dt > 0){
    if (dt > 2) dt = 2;                       // sanity clamp on absurd steps
    let left = dt;
    while (left > 1e-12){
      const h = left > SUB_DT ? SUB_DT : left;
      substep(h);
      left -= h;
    }
  }
  draw();
}

function allStopped(){
  for (let i=0;i<balls.length;i++){
    const b = balls[i];
    if (!b.potted && (b.vx !== 0 || b.vy !== 0)) return false;
  }
  return true;
}

function cueBall(){
  for (let i=0;i<balls.length;i++) if (balls[i].cue) return balls[i];
  return null;
}

function shoot(vx, vy){
  const c = cueBall();
  if (!c) return;
  if (c.potted){ respotCue(); }
  c.vx = num(vx, 0);
  c.vy = num(vy, 0);
}

function respotCue(){
  const c = cueBall();
  if (!c) return;
  let x = W*0.25, y = H/2;
  for (let tries=0; tries<400; tries++){
    let clear = true;
    for (let i=0;i<balls.length;i++){
      const b = balls[i];
      if (b === c || b.potted) continue;
      const dx = b.x-x, dy = b.y-y;
      if (dx*dx+dy*dy < (2*R+1)*(2*R+1)){ clear = false; break; }
    }
    if (clear) break;
    x -= 4;
    if (x < R+2){ x = W*0.25; y += 9; if (y > H-R-2) y = R+2; }
  }
  c.x = x; c.y = y; c.vx = 0; c.vy = 0; c.potted = false;
}

/* ------------------------------------------------------------------ *
 *  Rendering
 * ------------------------------------------------------------------ */
function roundRect(c, x, y, w, h, r){
  c.beginPath();
  c.moveTo(x+r, y);
  c.arcTo(x+w, y,   x+w, y+h, r);
  c.arcTo(x+w, y+h, x,   y+h, r);
  c.arcTo(x,   y+h, x,   y,   r);
  c.arcTo(x,   y,   x+w, y,   r);
  c.closePath();
}

function drawBall(b){
  if (b.potted) return;
  const n = b.n;
  const base = COLORS[n] !== undefined ? COLORS[n] : "#cccccc";
  const striped = n >= 9 && n <= 15;

  ctx.save();
  ctx.translate(b.x, b.y);

  // shadow
  ctx.beginPath();
  ctx.fillStyle = "rgba(0,0,0,.32)";
  ctx.ellipse(2.5, 3.5, R*0.98, R*0.82, 0, 0, Math.PI*2);
  ctx.fill();

  // body
  ctx.beginPath();
  ctx.arc(0,0,R,0,Math.PI*2);
  ctx.closePath();
  ctx.save();
  ctx.clip();

  ctx.fillStyle = striped ? "#f5f2e9" : base;
  ctx.fillRect(-R,-R,2*R,2*R);
  if (striped){
    ctx.fillStyle = base;
    ctx.fillRect(-R, -R*0.55, 2*R, R*1.1);
  }
  // shading
  const g = ctx.createRadialGradient(-R*0.35,-R*0.4,R*0.1, 0,0,R*1.15);
  g.addColorStop(0,"rgba(255,255,255,.55)");
  g.addColorStop(.45,"rgba(255,255,255,.05)");
  g.addColorStop(1,"rgba(0,0,0,.45)");
  ctx.fillStyle = g;
  ctx.fillRect(-R,-R,2*R,2*R);
  ctx.restore();

  // number badge
  if (n > 0){
    ctx.beginPath();
    ctx.arc(0,0,R*0.46,0,Math.PI*2);
    ctx.fillStyle = "#fbf9f3";
    ctx.fill();
    ctx.fillStyle = "#1a1a1a";
    ctx.font = "bold " + Math.round(R*0.72) + "px Arial";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(String(n), 0, 0.5);
  }

  ctx.beginPath();
  ctx.arc(0,0,R,0,Math.PI*2);
  ctx.strokeStyle = "rgba(0,0,0,.35)";
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.restore();
}

function draw(){
  const cw = W + MARGIN*2, ch = H + MARGIN*2;
  ctx.clearRect(0,0,cw,ch);

  // wooden frame
  const wood = ctx.createLinearGradient(0,0,0,ch);
  wood.addColorStop(0,"#7a4a22");
  wood.addColorStop(.5,"#5a3316");
  wood.addColorStop(1,"#38200c");
  ctx.fillStyle = wood;
  roundRect(ctx, 0, 0, cw, ch, 16); ctx.fill();

  ctx.strokeStyle = "rgba(0,0,0,.55)";
  ctx.lineWidth = 2;
  roundRect(ctx, 1, 1, cw-2, ch-2, 15); ctx.stroke();

  ctx.save();
  ctx.translate(MARGIN, MARGIN);

  // felt
  const felt = ctx.createRadialGradient(W*0.5,H*0.35,40, W*0.5,H*0.5,W*0.75);
  felt.addColorStop(0,"#1a8248");
  felt.addColorStop(1,"#0c5029");
  ctx.fillStyle = felt;
  ctx.fillRect(0,0,W,H);

  // inner rail shadow
  ctx.strokeStyle = "rgba(0,0,0,.35)";
  ctx.lineWidth = 6;
  ctx.strokeRect(3,3,W-6,H-6);

  // baulk line + spots
  ctx.strokeStyle = "rgba(255,255,255,.14)";
  ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(W*0.25,0); ctx.lineTo(W*0.25,H); ctx.stroke();
  ctx.fillStyle = "rgba(255,255,255,.13)";
  [[W*0.25,H/2],[W*0.68,H/2],[W/2,H/2]].forEach(function(p){
    ctx.beginPath(); ctx.arc(p[0],p[1],2.5,0,Math.PI*2); ctx.fill();
  });

  // pockets
  for (let i=0;i<POCKETS.length;i++){
    const p = POCKETS[i];
    const g = ctx.createRadialGradient(p.x,p.y,1,p.x,p.y,POCKET_DRAW);
    g.addColorStop(0,"#000");
    g.addColorStop(.75,"#050505");
    g.addColorStop(1,"rgba(0,0,0,.25)");
    ctx.beginPath(); ctx.arc(p.x,p.y,POCKET_DRAW,0,Math.PI*2);
    ctx.fillStyle = g; ctx.fill();
    ctx.strokeStyle = "rgba(230,215,180,.35)"; ctx.lineWidth = 2; ctx.stroke();
  }

  // balls
  for (let i=0;i<balls.length;i++) if (!balls[i].cue) drawBall(balls[i]);
  const c = cueBall();
  if (c) drawBall(c);

  // aim guide
  if (drag.active && c && !c.potted){
    const dx = c.x - drag.x, dy = c.y - drag.y;   // drag BACK => shoot forward
    const len = Math.hypot(dx,dy);
    if (len > 1){
      const ux = dx/len, uy = dy/len;
      const power = Math.min(1, len/170);

      // projected path (dashed)
      ctx.save();
      ctx.setLineDash([9,7]);
      ctx.strokeStyle = "rgba(255,255,255,.75)";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(c.x + ux*R, c.y + uy*R);
      ctx.lineTo(c.x + ux*(R + 60 + power*260), c.y + uy*(R + 60 + power*260));
      ctx.stroke();
      ctx.restore();

      // cue stick behind the ball
      ctx.save();
      ctx.strokeStyle = "#c99a52";
      ctx.lineWidth = 6;
      ctx.lineCap = "round";
      ctx.beginPath();
      ctx.moveTo(c.x - ux*(R + 6 + power*40), c.y - uy*(R + 6 + power*40));
      ctx.lineTo(c.x - ux*(R + 190 + power*40), c.y - uy*(R + 190 + power*40));
      ctx.stroke();
      ctx.strokeStyle = "#2b2b2b";
      ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.moveTo(c.x - ux*(R + 6 + power*40), c.y - uy*(R + 6 + power*40));
      ctx.lineTo(c.x - ux*(R + 26 + power*40), c.y - uy*(R + 26 + power*40));
      ctx.stroke();
      ctx.restore();

      // power bar
      const bw = 130, bh = 9, bx = c.x - bw/2, by = c.y + R + 20;
      ctx.fillStyle = "rgba(0,0,0,.5)";
      roundRect(ctx, bx-1, by-1, bw+2, bh+2, 5); ctx.fill();
      const pg = ctx.createLinearGradient(bx,0,bx+bw,0);
      pg.addColorStop(0,"#4fd06a"); pg.addColorStop(.55,"#f2d24b"); pg.addColorStop(1,"#e2482f");
      ctx.fillStyle = pg;
      roundRect(ctx, bx, by, Math.max(2, bw*power), bh, 4); ctx.fill();
    }
  }

  ctx.restore();
}

/* ------------------------------------------------------------------ *
 *  Animation loop
 * ------------------------------------------------------------------ */
function frame(t){
  if (!running) return;
  if (lastT === null) lastT = t;
  let dt = (t - lastT) / 1000;
  lastT = t;
  if (!(dt > 0)) dt = 0;
  if (dt > 0.05) dt = 0.05;              // don't let a stalled tab explode
  step(dt);

  // interactive-only housekeeping (never inside step(), so grading stays pure)
  const c = cueBall();
  if (c && c.potted && allStopped()) respotCue();
  updateStatus();

  rafId = requestAnimationFrame(frame);
}

function pause(){
  running = false;
  if (rafId !== null){ cancelAnimationFrame(rafId); rafId = null; }
  lastT = null;
  pauseBtn.textContent = "Resume";
}
function resume(){
  if (running && rafId !== null) return;
  running = true;
  lastT = null;
  pauseBtn.textContent = "Pause";
  rafId = requestAnimationFrame(frame);
}

/* ------------------------------------------------------------------ *
 *  Mouse / touch control
 * ------------------------------------------------------------------ */
const drag = {active:false, x:0, y:0};

function toField(ev){
  const r = cv.getBoundingClientRect();
  const sx = (W + MARGIN*2) / r.width;
  const sy = (H + MARGIN*2) / r.height;
  return {
    x: (ev.clientX - r.left) * sx - MARGIN,
    y: (ev.clientY - r.top ) * sy - MARGIN
  };
}

cv.addEventListener("pointerdown", function(ev){
  const c = cueBall();
  if (!c || c.potted) return;
  if (!allStopped()) return;               // wait for the table to settle
  const p = toField(ev);
  const d = Math.hypot(p.x - c.x, p.y - c.y);
  if (d > R * 3.2) return;                 // must press on (or very near) the cue ball
  drag.active = true;
  drag.x = p.x; drag.y = p.y;
  cv.setPointerCapture(ev.pointerId);
  ev.preventDefault();
  draw();
});

cv.addEventListener("pointermove", function(ev){
  if (!drag.active) return;
  const p = toField(ev);
  drag.x = p.x; drag.y = p.y;
  ev.preventDefault();
  if (!running) draw();
});

function releaseDrag(ev){
  if (!drag.active) return;
  drag.active = false;
  const c = cueBall();
  if (!c || c.potted){ draw(); return; }
  const dx = c.x - drag.x, dy = c.y - drag.y;
  const len = Math.hypot(dx,dy);
  if (len < 6){ draw(); return; }          // too small — treat as a cancel
  const power = Math.min(1, len/170);
  const sp = MAX_SHOT * power;
  shoot(dx/len * sp, dy/len * sp);
  if (!running) draw();
}
cv.addEventListener("pointerup", releaseDrag);
cv.addEventListener("pointercancel", function(){ drag.active = false; draw(); });
cv.addEventListener("contextmenu", function(e){ e.preventDefault(); });

/* ------------------------------------------------------------------ *
 *  UI
 * ------------------------------------------------------------------ */
const statusEl = document.getElementById("status");
const pauseBtn = document.getElementById("pauseBtn");

function updateStatus(){
  let potted = 0, left = 0;
  for (let i=0;i<balls.length;i++){
    const b = balls[i];
    if (b.cue) continue;
    if (b.potted) potted++; else left++;
  }
  let msg;
  if (drag.active) msg = "Aiming — release to shoot";
  else if (!allStopped()) msg = "Balls rolling…";
  else if (left === 0) msg = "Table cleared! Press Reset / Rack";
  else msg = "Ready — drag back from the cue ball";
  statusEl.textContent = msg + "   ·   potted " + potted + "/" + (potted+left);
}

document.getElementById("rack").addEventListener("click", function(){
  reset();
  updateStatus();
});
pauseBtn.addEventListener("click", function(){
  if (running) pause(); else resume();
});
window.addEventListener("keydown", function(e){
  if (e.key === "r" || e.key === "R"){ reset(); updateStatus(); }
  if (e.key === " "){ e.preventDefault(); if (running) pause(); else resume(); }
});

/* ------------------------------------------------------------------ *
 *  Public contract
 * ------------------------------------------------------------------ */
window.sim = {
  W: W,
  H: H,
  R: R,
  reset: reset,
  step: step,
  state: state,
  shoot: shoot,
  pause: pause,
  resume: resume
};

reset();
updateStatus();
resume();

})();
</script>
</body>
</html>
